esquema = ["fecha", "total", "proveedor"]

extraido = {"fecha": "2026-01-15", "total": 125.00, "proveedor": "Acme"}

def validar_contra_esquema(datos, esquema):
    return all(campo in datos for campo in esquema)

print(f"cumple el esquema: {validar_contra_esquema(extraido, esquema)}")
for campo in esquema:
    print(f"{campo}: {extraido[campo]}")
